window.NTI=window.NTI||{};(window.NTI.docs=window.NTI.docs||{})["ansible-87-mariadb-provisioning-br-with-ansible"]={"html":"\r\n\r\n\r\n\r\n▶ MariaDB Provisioning with Ansible — Project Documentation — By Nabawy\r\n\r\n\r\n\r\n\r\n\r\n<div class=\"sheet cover\">\r\n  <div class=\"stamp\">🗄️</div>\r\n  <div class=\"ckick\">REDLINE DAYLIGHT · PROJECT DOCUMENTATION</div>\r\n  <h1 id=\"mariadb-provisioningwith-ansible\">MariaDB Provisioning<br />with Ansible</h1>\r\n  <div class=\"ambrule\"></div>\r\n  <div class=\"sub\">Complete task documentation: automating a full <b>MariaDB</b> setup on Linux — packages, a custom configuration deployed under <b>/opt/mariadb</b>, an application database, a dedicated application user with scoped privileges, and schema seeding — all through one Ansible Role. <b>Repeatable, version-controlled, zero manual steps.</b></div>\r\n  <div class=\"byline\">By Nabawy<small>ENGINEERED &amp; DOCUMENTED</small></div>\r\n  <div class=\"vols\">\r\n    <div class=\"volcard on\">PROJECT DOC<small>Task Walkthrough</small></div>\r\n    <div class=\"volcard\">Ansible<small>Automation Engine</small></div>\r\n    <div class=\"volcard\">MariaDB<small>10.11.x</small></div>\r\n    <div class=\"volcard\">Jinja2<small>Templates</small></div>\r\n  </div>\r\n  <div class=\"cver\">IDEMPOTENT · VERSION-CONTROLLED · REPRODUCIBLE — BY NABAWY</div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Contents</div><h1 id=\"table-of-contents\">📖 Table of Contents</h1></div><span class=\"hmeta\">9 sections + extras</span></div></div>\r\n  <div class=\"tocgrid\">\r\n    <div>\r\n      <a href=\"#summary\"><span class=\"tnum\">🗺️</span><span>The Map — Executive Summary</span><span class=\"dots\"></span><span class=\"tp\">3</span></a>\r\n      <a href=\"#sec-01\"><span class=\"tnum\">01</span><span>Objective &amp; End State</span><span class=\"dots\"></span><span class=\"tp\">4</span></a>\r\n      <a href=\"#sec-02\"><span class=\"tnum\">02</span><span>The Tools — What &amp; Why</span><span class=\"dots\"></span><span class=\"tp\">5</span></a>\r\n      <a href=\"#sec-03\"><span class=\"tnum\">03</span><span>Project Structure — The Tree</span><span class=\"dots\"></span><span class=\"tp\">6</span></a>\r\n      <a href=\"#sec-04a\"><span class=\"tnum\">04</span><span>Steps 1–3 — Install · Service · Folder</span><span class=\"dots\"></span><span class=\"tp\">7</span></a>\r\n      <a href=\"#sec-04b\"><span class=\"tnum\">04·b</span><span>Steps 4–5 — Config Deploy + Restart</span><span class=\"dots\"></span><span class=\"tp\">8</span></a>\r\n      <a href=\"#sec-04c\"><span class=\"tnum\">04·c</span><span>Steps 6–8 — DB · User · Seed</span><span class=\"dots\"></span><span class=\"tp\">9</span></a>\r\n    </div>\r\n    <div>\r\n      <a href=\"#sec-05\"><span class=\"tnum\">05</span><span>Running It — The Commands</span><span class=\"dots\"></span><span class=\"tp\">10</span></a>\r\n      <a href=\"#sec-06\"><span class=\"tnum\">06</span><span>Verifying the Result</span><span class=\"dots\"></span><span class=\"tp\">11</span></a>\r\n      <a href=\"#sec-07\"><span class=\"tnum\">07</span><span>Adding New Data</span><span class=\"dots\"></span><span class=\"tp\">12</span></a>\r\n      <a href=\"#sec-08\"><span class=\"tnum\">08</span><span>Viewing the Data — 4 Ways</span><span class=\"dots\"></span><span class=\"tp\">13</span></a>\r\n      <a href=\"#sec-09\"><span class=\"tnum\">09</span><span>Gotchas — Lessons From the Trench</span><span class=\"dots\"></span><span class=\"tp\">14</span></a>\r\n      <a href=\"#cheatsheet\"><span class=\"tnum\">📌</span><span>Cheat Sheet</span><span class=\"dots\"></span><span class=\"tp\">15</span></a>\r\n    </div>\r\n  </div>\r\n  <div class=\"taskhead\">TASK [Prerequisites]<span class=\"hst\">before reading</span></div>\r\n  <div class=\"mark m-tip\"><span class=\"tag\">DEBUG</span><b>What this document is:</b> the full engineering record of one automation task — why each piece exists, what every step does, how to run it, how to verify it, and the traps actually hit along the way. Assumes basic Ansible familiarity (playbooks, roles, handlers, templates). If a concept is fuzzy, this doc still shows the commands and results end to end.</div>\r\n  <div class=\"folio\"><span>📘 MariaDB Provisioning · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 2 —</span><span><a href=\"#toc\">▤ TOC</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Executive Summary</div><h1 id=\"the-map-the-whole-task\">🗺️ The Map — The Whole Task</h1></div><span class=\"hmeta\">start here</span></div></div>\r\n  <p>One Ansible Role, eight steps, one running MariaDB server. Here's the route — every line links to its section.</p>\r\n  <p>The mission is defined in <a href=\"#sec-01\">Section 1 — Objective &amp; End State</a>: automate a complete MariaDB setup so it's repeatable and version-controlled — ending with a custom config under <code>/opt/mariadb</code>, an application database, a dedicated user, and seeded schema. The cast of tools is listed in <a href=\"#sec-02\">Section 2</a>: Ansible as the engine, the <b>community.mysql</b> collection for DB/user management, PyMySQL on the target, and Jinja2 templates for rendering config.</p>\r\n  <p>The battlefield layout is in <a href=\"#sec-03\">Section 3 — Project Structure</a>: a playbook entry point, an inventory, requirements, group_vars for the secret, and the <b>mariadb role</b> holding everything. Then the build itself, in three pages: <a href=\"#sec-04a\">Steps 1–3</a> (install packages, enable &amp; start the service, create the config folder), <a href=\"#sec-04b\">Steps 4–5</a> (deploy my.cnf + initdb.sql from templates, symlink into the OS config path, restart via handler with a flush), and <a href=\"#sec-04c\">Steps 6–8</a> (create the database, create the user with scoped grants, import the seed SQL).</p>\r\n  <p>Operations: <a href=\"#sec-05\">Section 5 — Running It</a> (collection install + the playbook command with the password extra-var), <a href=\"#sec-06\">Section 6 — Verifying</a> (five checks from service status to seeded rows), <a href=\"#sec-07\">Section 7 — Adding Data</a> (one-off vs permanent), and <a href=\"#sec-08\">Section 8 — Viewing the Data</a> (four ways, including what never to edit). Finally, the scars: <a href=\"#sec-09\">Section 9 — Gotchas</a>, and the condensed <a href=\"#cheatsheet\">Cheat Sheet</a>. Route clear. ▶</p>\r\n  <div class=\"m-key\"><span class=\"tag\">KEY IDEA</span><b>The promise of this task:</b> the same playbook, run on any fresh Linux server, produces the exact same working MariaDB — config, database, user, and data. No memory, no manual steps, no drift.</div>\r\n  <div class=\"folio\"><span>📘 MariaDB Provisioning · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 3 —</span><span><a href=\"#toc\">▤ TOC</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Section 01</div><h1 id=\"objective-amp-end-state\">🎯 Objective &amp; End State</h1></div><span class=\"hmeta\">🟢 4 MIN</span></div></div>\r\n  <p><b>The mission:</b> automate a complete MariaDB setup on a Linux server using Ansible — so the whole process is <b>repeatable, version-controlled, and doesn't rely on manual steps</b>.</p>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>This isn't \"install a database.\" It's \"<b>encode a database setup into code</b>\" — so any server, any time, run once, ends up identical. The value isn't the first run; it's the hundredth run being free.</div>\r\n  <div class=\"taskhead\">TASK [The End State]<span class=\"hst\">what exists when the playbook finishes</span></div>\r\n  <p>A running MariaDB server with all four of these:</p>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>1️⃣ Custom configuration</p><p>Deployed from a known location — <code>/opt/mariadb</code> — charset, port, max connections, InnoDB buffer pool. Not hidden in OS default files.</p></div>\r\n    <div class=\"panel\"><p>2️⃣ An application database</p><p>A dedicated database (default: <code>myapp_db</code>) created only if it doesn't already exist.</p></div>\r\n    <div class=\"panel\"><p>3️⃣ A dedicated application user</p><p>(default: <code>myapp_user</code>@<code>localhost</code>) with <b>full privileges on that database only</b> — not the whole server.</p></div>\r\n    <div class=\"panel\"><p>4️⃣ Initialized schema &amp; seed data</p><p>The database starts with its tables and initial rows from a versioned SQL script.</p></div>\r\n  </div>\r\n  <div class=\"taskhead\">TASK [Why this matters]<span class=\"hst\">manual vs automated</span></div>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>❌ Manual setup</p><p>SSH in, remember the package names, edit config by hand, restart, create DB in a client, forget whether you granted the user… Every server becomes its own snowflake. Recovery = archaeology.</p></div>\r\n    <div class=\"panel\"><p>✅ This task</p><p>One playbook, one command. The server's entire DB setup lives in <b>Git</b> — reviewable, revertible, and identical on every machine it touches.</p></div>\r\n  </div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 TAKEAWAY</span>The four end-state items are the <b>acceptance criteria</b> of the whole task. If verification (Section 6) can prove all four, the automation is done — regardless of how many steps it took.</div>\r\n  <p>⏭️ What tools make this possible? → <a href=\"#sec-02\">Section 2: The Tools</a></p>\r\n  <div class=\"folio\"><span>📘 MariaDB Provisioning · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 4 —</span><span><a href=\"#toc\">▤ TOC</a> ▶ <a href=\"#sec-02\">Next</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Section 02</div><h1 id=\"the-tools-what-amp-why\">🧰 The Tools <span class=\"en\">— What &amp; Why</span></h1></div><span class=\"hmeta\">🟡 5 MIN</span></div></div>\r\n  <p>Six tools carry this task. Knowing <b>why each one exists</b> matters more than knowing their names.</p>\r\n  <div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n    <tr><th>Tool</th><th>Purpose</th></tr>\r\n    <tr><td><b>Ansible</b></td><td>The automation engine — runs all the steps <b>idempotently</b> (safe to re-run, changes only what needs changing).</td></tr>\r\n    <tr><td><b>community.mysql</b> collection</td><td>Provides the <code>mysql_db</code> and <code>mysql_user</code> modules for database and user management.</td></tr>\r\n    <tr><td><b>community.general</b> collection</td><td>Supporting modules used alongside the core set.</td></tr>\r\n    <tr><td><b>MariaDB</b></td><td>The database server itself — version 10.11.x, installed via the OS package manager.</td></tr>\r\n    <tr><td><b>PyMySQL</b></td><td>The Python library that Ansible's mysql modules need <b>on the target host</b> to connect and run SQL.</td></tr>\r\n    <tr><td><b>Jinja2 templates</b></td><td>Used to render <code>my.cnf</code> and <code>initdb.sql</code> from variables — one template, many environments.</td></tr>\r\n    <tr><td><b>mysql client / mysqldump</b></td><td>Manual verification, querying, and backups — the human-side tools after automation finishes.</td></tr>\r\n  </table></div></div>\r\n  <div class=\"taskhead\">TASK [The two most-misunderstood pieces]<span class=\"hst\">clarifications</span></div>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>🐍 Why PyMySQL on the target?</p><p>Ansible is agentless — but its <code>mysql_db</code>/<code>mysql_user</code> modules execute <b>on the managed node</b> and speak to MariaDB through a Python driver. No PyMySQL → the DB tasks fail with a \"python mysql module not found\" error, even though MariaDB itself is running fine.</p></div>\r\n    <div class=\"panel\"><p>📦 Why a \"collection\"?</p><p><code>community.mysql</code> isn't shipped with Ansible core — it's a Galaxy collection that must be installed first (Section 5). Forgetting this = \"couldn't resolve module\" on the very first DB task.</p></div>\r\n  </div>\r\n  <div class=\"mark m-tip\"><span class=\"tag\">DEBUG · The division of labor</span>Ansible = <b>the conductor</b> (order and idempotency) · MariaDB = <b>the musician</b> (the actual server) · PyMySQL = <b>the translator</b> between them · Jinja2 = <b>the copywriter</b> (renders config per environment) · mysql client/mysqldump = <b>the inspector</b> after the show.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 TAKEAWAY</span>Three install-time dependencies people forget: the <b>collections</b> (on the control node, via requirements.yml), <b>PyMySQL</b> (on the target, installed by the role itself in Step 1), and MariaDB's own packages. All three are handled by the automation — that's the point.</div>\r\n  <p>⏭️ Where does all of this live on disk? → <a href=\"#sec-03\">Section 3: Project Structure</a></p>\r\n  <div class=\"folio\"><span>📘 MariaDB Provisioning · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 5 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#sec-01\">Prev</a> · <a href=\"#sec-03\">Next</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Section 03</div><h1 id=\"project-structure-the-tree\">🌳 Project Structure <span class=\"en\">— The Tree</span></h1></div><span class=\"hmeta\">🟡 5 MIN</span></div></div>\r\n  <p>Every file in the project, and what it's for. This tree <b>is</b> the architecture:</p>\r\n  <div class=\"tree\"><b>mariadb_project/</b>\r\n├── playbook.yml              <span class=\"g\"># Entry point — runs the mariadb role</span>\r\n├── inventory.ini             <span class=\"g\"># Target host(s)</span>\r\n├── requirements.yml          <span class=\"g\"># Ansible Galaxy collections needed</span>\r\n├── group_vars/\r\n│   └── db_servers/\r\n│       └── vault.yml.example <span class=\"g\"># Template for storing the DB password securely</span>\r\n└── roles/\r\n    └── <b>mariadb/</b>\r\n        ├── <u>defaults/main.yml</u> <span class=\"g\"># All tunable variables (db name, user, password…)</span>\r\n        ├── <i>vars/</i>\r\n        │   ├── <i>Debian.yml</i>    <span class=\"g\"># apt-based package/service names</span>\r\n        │   └── <i>RedHat.yml</i>    <span class=\"g\"># dnf/yum-based package/service names</span>\r\n        ├── <u>tasks/main.yml</u>    <span class=\"g\"># The 8 provisioning steps</span>\r\n        ├── <i>handlers/main.yml</i> <span class=\"g\"># Restart handler</span>\r\n        └── <em>templates/</em>\r\n            ├── <em>my.cnf.j2</em>     <span class=\"g\"># Config file template</span>\r\n            └── <em>initdb.sql.j2</em> <span class=\"g\"># DB init/seed script template</span></div>\r\n  <div class=\"taskhead\">TASK [Reading the tree]<span class=\"hst\">four things to notice</span></div>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>🗂️ vars/ split by family</p><p><code>Debian.yml</code> vs <code>RedHat.yml</code> — package and service <b>names differ per distro</b>. The role loads the right file per OS, so the same task code works everywhere.</p></div>\r\n    <div class=\"panel\"><p>🔐 vault.yml.example</p><p>The <b>.example</b> suffix is deliberate: it's a template to copy into your own (Ansible-Vault-encrypted) file. The real password never enters Git.</p></div>\r\n    <div class=\"panel\"><p>📄 Two Jinja2 templates</p><p><code>my.cnf.j2</code> (server config) and <code>initdb.sql.j2</code> (schema + seed) — both rendered from variables, both living inside the role's templates/ folder.</p></div>\r\n    <div class=\"panel\"><p>🎯 defaults/main.yml</p><p>Every tunable in one place: db name, user name, password reference, ports, buffer sizes. Override from the playbook or extra-vars without touching the role.</p></div>\r\n  </div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>The layout is standard Ansible role convention — which means <b>any Ansible engineer can navigate this project without a guide</b>. Convention is documentation that never goes stale.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 TAKEAWAY</span>Entry point = <code>playbook.yml</code> → calls role <code>mariadb</code> → which carries tasks (8 steps), handlers (restart), templates (2 files), OS-specific vars, and defaults. Everything else in the tree is plumbing for that flow.</div>\r\n  <p>⏭️ The tree is static — now the 8 steps that make it run: → <a href=\"#sec-04a\">Steps 1–3</a></p>\r\n  <div class=\"folio\"><span>📘 MariaDB Provisioning · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 6 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#sec-02\">Prev</a> · <a href=\"#sec-04a\">Next</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Section 04 · Part 1 of 3</div><h1 id=\"steps-1-3-install-service-folder\">🧱 Steps 1–3 <span class=\"en\">— Install · Service · Folder</span></h1></div><span class=\"hmeta\">🟠 7 MIN</span></div></div>\r\n  <p>The foundation phase: get MariaDB on the machine, running, and a home ready for its custom config.</p>\r\n  <div class=\"stepitem\"><div class=\"stepnum\">1</div><div>\r\n    <p>Install MariaDB + PyMySQL</p>\r\n    <p>The role installs <code>mariadb-server</code> and <code>mariadb-client</code> (Debian) or <code>mariadb-server</code>/<code>mariadb</code> (RedHat) via the <b>OS package manager</b> — plus <b>PyMySQL</b>, so Ansible's mysql modules can connect later in Steps 6–8. The OS-specific package names come from the vars/<code>Debian.yml</code> / <code>RedHat.yml</code> split.</p>\r\n  </div></div>\r\n  <div class=\"stepitem\"><div class=\"stepnum\">2</div><div>\r\n    <p>Enable and start the service</p>\r\n    <p>The <code>mariadb</code> systemd service is <b>enabled</b> (starts on boot) and <b>started</b> immediately. Both in one task — a fresh server goes from \"no database\" to \"database accepting local connections\" in a single step.</p>\r\n  </div></div>\r\n  <div class=\"stepitem\"><div class=\"stepnum\">3</div><div>\r\n    <p>Create the configuration folder</p>\r\n    <p>A directory is created at <code><b>/opt/mariadb</b></code> to hold the custom config and init script — kept <b>separate from the OS's default config locations</b>. Everything this deployment owns lives in one known place.</p>\r\n  </div></div>\r\n  <div class=\"zone\">\r\n    <div class=\"zlabel\">After steps 1–3 — the server state</div>\r\n    <div class=\"frow\">\r\n      <span class=\"chipr\">📦 mariadb-server installed</span>\r\n      <span class=\"harrow\">+</span>\r\n      <span class=\"chipr\">🐍 PyMySQL installed</span>\r\n      <span class=\"harrow\">+</span>\r\n      <span class=\"chipr\">⚡ service: enabled + started</span>\r\n      <span class=\"harrow\">+</span>\r\n      <span class=\"chipr\">📁 /opt/mariadb/ ready</span>\r\n    </div>\r\n  </div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>Step 1's quiet hero is <b>PyMySQL</b> — installing it now, alongside the packages, means Steps 6–8 won't fail later with \"mysql module not found.\" Front-loading dependencies is what makes the playbook run top-to-bottom without surprises.</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>Why <code>/opt/mariadb</code> instead of editing the OS config directly? <b>Ownership and clarity.</b> The OS owns <code>/etc/mysql/...</code>; this deployment owns <code>/opt/mariadb</code>. One folder to back up, inspect, or blow away — no guessing which lines in the default config were \"ours.\"</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 TAKEAWAY</span>Steps 1–3 are pure preparation: <b>packages + service + a home directory</b>. Nothing custom has landed yet — that's Steps 4–5. Keeping setup and configuration as separate steps is what makes failures easy to locate.</div>\r\n  <p>⏭️ The custom config lands — and MariaDB actually reads it: → <a href=\"#sec-04b\">Steps 4–5</a></p>\r\n  <div class=\"folio\"><span>📘 MariaDB Provisioning · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 7 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#sec-03\">Prev</a> · <a href=\"#sec-04b\">Next</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Section 04 · Part 2 of 3</div><h1 id=\"steps-4-5-config-deploy-restart\">📄 Steps 4–5 <span class=\"en\">— Config Deploy + Restart</span></h1></div><span class=\"hmeta\">🟠 8 MIN</span></div></div>\r\n  <p>The most interesting pair of steps: render the custom files from templates, make MariaDB actually <b>read</b> them, and restart at exactly the right moment.</p>\r\n  <div class=\"stepitem\"><div class=\"stepnum\">4</div><div>\r\n    <p>Deploy the config file and init script</p>\r\n    <ul>\r\n      <li>📄 <code>my.cnf</code> is rendered from <code>templates/my.cnf.j2</code> into <code>/opt/mariadb/my.cnf</code> — charset, port, max connections, InnoDB buffer pool size, etc.</li>\r\n      <li>📄 <code>initdb.sql</code> is rendered from <code>templates/initdb.sql.j2</code> into <code>/opt/mariadb/initdb.sql</code>.</li>\r\n      <li>🔗 Because MariaDB <b>doesn't read /opt by default</b>, the role <b>symlinks</b> the config into the distro's real include directory — so the settings actually take effect.</li>\r\n    </ul>\r\n  </div></div>\r\n  <div class=\"zone\">\r\n    <div class=\"zlabel\">The symlink bridge — where the config goes per distro</div>\r\n    <div class=\"frow\">\r\n      <span class=\"chipr\">/opt/mariadb/my.cnf<small> the real file</small></span>\r\n      <span class=\"harrow\">── symlink ──►</span>\r\n      <span class=\"chipr\">Debian: /etc/mysql/mariadb.conf.d/99-custom.cnf</span>\r\n    </div>\r\n    <div class=\"frow\">\r\n      <span class=\"chipr\">/opt/mariadb/my.cnf</span>\r\n      <span class=\"harrow\">── symlink ──►</span>\r\n      <span class=\"chipr\">RedHat: /etc/my.cn.d/</span>\r\n    </div>\r\n    <p>Same source file, different landing spot per OS family — the vars/ split from Section 3 decides which.</p>\r\n  </div>\r\n  <div class=\"stepitem\"><div class=\"stepnum\">5</div><div>\r\n    <p>Restart MariaDB — via handler, flushed immediately</p>\r\n    <p>The config deployment <b>notifies a handler</b> that restarts the <code>mariadb</code> service — and the playbook <b>flushes handlers immediately</b> so the new configuration is <b>live before the next steps run</b>. The DB creation in Steps 6–8 must talk to a server that's already loaded the new settings.</p>\r\n  </div></div>\r\n  <div class=\"zone\">\r\n    <div class=\"zlabel\">Why the flush matters — the timing</div>\r\n    <div class=\"frow\">\r\n      <span class=\"chipr\">Step 4: config changes</span>\r\n      <span class=\"harrow\">── notify ──►</span>\r\n      <span class=\"chipr\">handler: restart (queued)</span>\r\n      <span class=\"harrow\">── meta: flush_handlers ──►</span>\r\n      <span class=\"chipr\">✅ new config live</span>\r\n      <span class=\"harrow\">──►</span>\r\n      <span class=\"chipr\">Steps 6–8 run against it</span>\r\n    </div>\r\n  </div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>Two classic Ansible patterns working together: the <b>handler</b> guarantees a restart happens only when the config actually changed (idempotent runs = no pointless restarts), and the <b>flush</b> guarantees the restart lands <b>before</b> dependent steps — not at the end of the play, when it's too late.</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>Drop the flush, and Steps 6–8 could run against MariaDB still using the <b>old</b> config — for example the wrong charset or buffer settings, silently. The handler fires eventually, but your DB was created under the wrong settings.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 TAKEAWAY</span>Step 4 in one line: <b>render two templates into /opt/mariadb, then symlink my.cnf into the OS include path</b> (Debian: <code>mariadb.conf.d/99-custom.cnf</code> · RedHat: <code>/etc/my.cnf.d/</code>). Step 5: <b>notify restart + flush_handlers</b> = config live exactly when needed.</div>\r\n  <p>⏭️ Server ready and configured — now fill it: database, user, data → <a href=\"#sec-04c\">Steps 6–8</a></p>\r\n  <div class=\"folio\"><span>📘 MariaDB Provisioning · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 8 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#sec-04a\">Prev</a> · <a href=\"#sec-04c\">Next</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Section 04 · Part 3 of 3</div><h1 id=\"steps-6-8-db-user-seed\">🐬 Steps 6–8 <span class=\"en\">— DB · User · Seed</span></h1></div><span class=\"hmeta\">🟠 8 MIN</span></div></div>\r\n  <p>With MariaDB installed, configured, and freshly restarted — the actual database assets get created. All three steps use the <b>community.mysql</b> collection modules, all three are idempotent.</p>\r\n  <div class=\"stepitem\"><div class=\"stepnum\">6</div><div>\r\n    <p>Create the database</p>\r\n    <p><code>community.mysql.mysql_db</code> creates the application database — default name <code>myapp_db</code> — <b>if it doesn't already exist</b>. Second run? The database is there → status <span class=\"stbad st-ok\">ok</span>, untouched.</p>\r\n  </div></div>\r\n  <div class=\"stepitem\"><div class=\"stepnum\">7</div><div>\r\n    <p>Create the user and grant privileges</p>\r\n    <p><code>community.mysql.mysql_user</code> creates the application user — default <code>myapp_user</code>@<code>localhost</code> — and grants <b>ALL PRIVILEGES on the new database only</b>.</p>\r\n    <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA · Scope matters</span>\"On the new database only — not on the whole server.\" The app can fully own its own database but cannot touch <code>mysql.*</code>, other databases, or server settings. Least privilege, enforced at grant time.</div>\r\n  </div></div>\r\n  <div class=\"stepitem\"><div class=\"stepnum\">8</div><div>\r\n    <p>Initialize the database</p>\r\n    <p><code>community.mysql.mysql_db</code> with <code>state: import</code> runs <code>/opt/mariadb/initdb.sql</code> against the new database — creating the starting schema/tables and seeding the initial rows. The SQL itself came from the <code>initdb.sql.j2</code> template rendered back in Step 4.</p>\r\n  </div></div>\r\n  <div class=\"zone\">\r\n    <div class=\"zlabel\">Steps 6–8 — the chain</div>\r\n    <div class=\"frow\">\r\n      <span class=\"chipr\">6️⃣ mysql_db<small> create myapp_db</small></span>\r\n      <span class=\"harrow\">──►</span>\r\n      <span class=\"chipr\">7️⃣ mysql_user<small> myapp_user + grants</small></span>\r\n      <span class=\"harrow\">──►</span>\r\n      <span class=\"chipr\">8️⃣ mysql_db<small> state: import initdb.sql</small></span>\r\n    </div>\r\n    <p>Order is mandatory: no database → nowhere to create the user's grants · no user → the import could still work but the app couldn't connect · no import → empty schema.</p>\r\n  </div>\r\n  <div class=\"mark m-ok\"><span class=\"tag\">PROOF · Idempotency across all three</span>Run the playbook again tomorrow: the DB exists (<span class=\"stbad st-ok\">ok</span>), the user exists with identical grants (<span class=\"stbad st-ok\">ok</span>), and the import behavior keeps the state consistent instead of duplicating rows blindly. The whole playbook is safe to re-run — that's the entire design goal.</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>The <code>-e mariadb_db_password='…'</code> you pass at run time (Section 5) is what Steps 7's user creation uses. Lose it or change it between runs → the task reports a change or fails to connect. The password is part of the <b>state</b>, not just a one-time secret.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 TAKEAWAY</span>The final triad: <b>6</b> <code>mysql_db</code> create (name: myapp_db) · <b>7</b> <code>mysql_user</code> create + <b>ALL PRIVILEGES scoped to that DB only</b> · <b>8</b> <code>mysql_db state: import</code> from <code>/opt/mariadb/initdb.sql</code>. Database → user → data, in that order, every run.</div>\r\n  <p>⏭️ All 8 steps done — time to press the button for real: → <a href=\"#sec-05\">Section 5: Running It</a></p>\r\n  <div class=\"folio\"><span>📘 MariaDB Provisioning · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 9 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#sec-04b\">Prev</a> · <a href=\"#sec-05\">Next</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Section 05</div><h1 id=\"running-it-the-commands\">▶️ Running It <span class=\"en\">— The Commands</span></h1></div><span class=\"hmeta\">🟠 6 MIN</span></div></div>\r\n  <p>Two commands from a fresh clone to a running database. First the terminal, then what every piece means:</p>\r\n  <div class=\"taskhead\">TASK [The exact commands]<span class=\"hst\">from the project root</span></div>\r\n  <div class=\"code\"><span class=\"g\">cd mariadb_project</span>\r\n\r\n<span class=\"g\"># Install required collections</span>\r\n<span class=\"p\">$</span> ansible-galaxy collection install <span class=\"y\">-r</span> requirements.yml\r\n\r\n<span class=\"g\"># Run the playbook</span>\r\n<span class=\"p\">$</span> ansible-playbook <span class=\"y\">-i</span> inventory.ini playbook.yml \\\r\n  <span class=\"y\">--ask-become-pass</span> \\\r\n  <span class=\"y\">-e</span> mariadb_db_password=<span class=\"s\">'YourStrongPassword'</span></div>\r\n  <div class=\"taskhead\">TASK [The inventory note]<span class=\"hst\">pointing at your target</span></div>\r\n  <p><code>inventory.ini</code> should point at the target host — two common shapes:</p>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>💻 Local testing</p><div class=\"code mini\"><span class=\"c\">localhost ansible_connection=local</span></div><p>Runs against the same machine — no SSH involved.</p></div>\r\n    <div class=\"panel\"><p>🌐 Remote server</p><div class=\"code mini\"><span class=\"c\">myserver ansible_host=10.0.0.5</span></div><p>A real hostname/IP — uses standard SSH.</p></div>\r\n  </div>\r\n  <div class=\"taskhead\">TASK [Every flag decoded]<span class=\"hst\">nothing is magic</span></div>\r\n  <div class=\"grid3\">\r\n    <div class=\"blk\"><span class=\"mono\">-i inventory.ini</span><small>which hosts to run against</small></div>\r\n    <div class=\"blk\"><span class=\"mono\">--ask-become-pass</span><small>prompts for the sudo password (package installs need root)</small></div>\r\n    <div class=\"blk\"><span class=\"mono\">-e var=value</span><small>extra-var — injects the DB password into the run</small></div>\r\n  </div>\r\n  <div class=\"mark m-tip\"><span class=\"tag\">DEBUG · The two commands, in order</span><b>Command 1</b> stocks your control node with the <b>community.mysql</b> and <b>community.general</b> collections (Section 2). <b>Command 2</b> does the actual work on the target. Skip command 1 → command 2 dies on its first mysql task with \"module not found.\"</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>The <code>-e</code> password ends up in your shell history. For anything beyond a lab, prefer the <code>group_vars/db_servers/vault.yml</code> route (encrypted with Ansible-Vault — see the project structure, Section 3) and drop the <code>-e</code> flag entirely.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 TAKEAWAY</span>The run recipe: <b>cd → galaxy collections → playbook with inventory + become password + DB password extra-var</b>. Local test = <code>ansible_connection=local</code>; remote = real host in inventory.ini.</div>\r\n  <p>⏭️ It ran — but \"it ran\" isn't \"it works.\" Prove it: → <a href=\"#sec-06\">Section 6: Verifying</a></p>\r\n  <div class=\"folio\"><span>📘 MariaDB Provisioning · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 10 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#sec-04c\">Prev</a> · <a href=\"#sec-06\">Next</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Section 06</div><h1 id=\"verifying-the-result\">✅ Verifying the Result</h1></div><span class=\"hmeta\">🟡 6 MIN</span></div></div>\r\n  <p>A finished playbook proves <b>nothing</b> — a green recap means the tasks ran, not that the outcome is correct. Five checks, each mapping to one end-state promise from Section 1:</p>\r\n  <div class=\"taskhead\">TASK [Check 1 — the service is alive]<span class=\"hst\">end state: running server</span></div>\r\n  <div class=\"code\"><span class=\"p\">$</span> sudo systemctl status mariadb <span class=\"y\">--no-pager</span>\r\n<span class=\"ok\">● mariadb.service — MariaDB 10.11.x database server\r\n   Active: active (running)</span></div>\r\n  <div class=\"taskhead\">TASK [Check 2 — the custom config actually applied]<span class=\"hst\">end state: /opt/mariadb config live</span></div>\r\n  <div class=\"code\"><span class=\"p\">$</span> sudo mysql <span class=\"y\">-e</span> <span class=\"s\">\"SHOW VARIABLES LIKE 'character_set_server';\"</span>\r\n<span class=\"g\">+----------------------+---------+</span>\r\n<span class=\"ok\">character_set_server   utf8mb4</span>   <span class=\"g\">← proves the symlinked config loaded</span></div>\r\n  <div class=\"taskhead\">TASK [Checks 3 &amp; 4 — database and user exist]<span class=\"hst\">end states: DB + scoped user</span></div>\r\n  <div class=\"code\"><span class=\"p\">$</span> sudo mysql <span class=\"y\">-e</span> <span class=\"s\">\"SHOW DATABASES;\"</span>\r\n<span class=\"ok\">myapp_db</span>                      <span class=\"g\">← the application database is there</span>\r\n\r\n<span class=\"p\">$</span> sudo mysql <span class=\"y\">-e</span> <span class=\"s\">\"SHOW GRANTS FOR 'myapp_user'@'localhost';\"</span>\r\n<span class=\"ok\">GRANT ALL PRIVILEGES ON `myapp_db`.* TO …</span>   <span class=\"g\">← scoped, not server-wide</span></div>\r\n  <div class=\"taskhead\">TASK [Check 5 — seeded data is present]<span class=\"hst\">end state: schema + rows</span></div>\r\n  <div class=\"code\"><span class=\"p\">$</span> sudo mysql myapp_db <span class=\"y\">-e</span> <span class=\"s\">\"SELECT * FROM app_info;\"</span>\r\n<span class=\"g\">…seeded rows appear…</span>         <span class=\"g\">← Step 8's import actually landed</span></div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>Each check targets a <b>specific step</b> from Section 4: status → Step 2 · charset variable → Step 4 (config live) · SHOW DATABASES → Step 6 · SHOW GRANTS → Step 7 · SELECT → Step 8. If all five pass, every layer of the automation is proven — not just \"it didn't crash.\"</div>\r\n  <div class=\"mark m-tip\"><span class=\"tag\">DEBUG · The cleverest check</span>Check 2 is the one people skip — and the one that catches the most. MariaDB <b>starting fine</b> doesn't mean it read your custom config. Querying a variable you set in <code>my.cnf.j2</code> is the only direct proof the symlink bridge worked.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 TAKEAWAY</span>The verification set: <code>systemctl status</code> · <code>SHOW VARIABLES</code> · <code>SHOW DATABASES</code> · <code>SHOW GRANTS</code> · <code>SELECT</code>. Five commands = five end-state promises verified. Keep them in your runbook next to the playbook.</div>\r\n  <p>⏭️ Verified and running — now the day-2 question: how does new data get in? → <a href=\"#sec-07\">Section 7</a></p>\r\n  <div class=\"folio\"><span>📘 MariaDB Provisioning · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 11 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#sec-05\">Prev</a> · <a href=\"#sec-07\">Next</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Section 07</div><h1 id=\"adding-new-data-two-paths\">➕ Adding New Data <span class=\"en\">— Two Paths</span></h1></div><span class=\"hmeta\">🟡 5 MIN</span></div></div>\r\n  <p>There are two legitimate ways to put new data into this database — and they serve <b>different purposes</b>. Knowing which to reach for is the whole lesson.</p>\r\n  <div class=\"taskhead\">TASK [Path 1 — one-off, via the mysql client]<span class=\"hst\">quick, manual, not reproducible</span></div>\r\n  <div class=\"code\"><span class=\"p\">$</span> mysql <span class=\"y\">-u</span> myapp_user <span class=\"y\">-p</span><span class=\"s\">'YourStrongPassword'</span> <span class=\"y\">-D</span> myapp_db \\\r\n  <span class=\"y\">-e</span> <span class=\"s\">\"INSERT INTO app_info (key_name, value) VALUES ('app_name', 'MyApp');\"</span></div>\r\n  <p>Fast for a quick test row or an ad-hoc fix. But: it lives only on this server, in this moment — a rebuilt machine won't have it.</p>\r\n  <div class=\"taskhead\">TASK [Path 2 — permanent / repeatable, via the role]<span class=\"hst\">the Ansible way</span></div>\r\n  <p>Add your <code>CREATE TABLE</code> / <code>INSERT</code> statements to <code>roles/mariadb/templates/initdb.sql.j2</code>, then <b>rerun the playbook</b> — so the schema stays <b>reproducible on any server it's deployed to</b>:</p>\r\n  <div class=\"zone\">\r\n    <div class=\"frow\">\r\n      <span class=\"chipr\">✏️ edit initdb.sql.j2</span>\r\n      <span class=\"harrow\">──►</span>\r\n      <span class=\"chipr\">▶ rerun playbook</span>\r\n      <span class=\"harrow\">──►</span>\r\n      <span class=\"chipr\">✅ schema reproducible everywhere</span>\r\n    </div>\r\n  </div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA · The decision rule</span><b>Will this data need to exist on the next server too?</b> Yes → it belongs in <code>initdb.sql.j2</code> (version-controlled, part of the state). No → the mysql client is fine. Everything reproducible goes in code; everything throwaway stays in the client.</div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT</span>Remember from Step 8: the import runs against the DB at provision time. A brand-new server gets the <b>full updated initdb.sql</b>; an existing server only picks up changes the next time its state is reconciled — for row-level data on live servers, the client (or a migration task) is the operational path.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 TAKEAWAY</span>One-off row/test = <b>mysql client INSERT</b> · permanent schema/seed = <b>edit initdb.sql.j2 + rerun</b>. The second path is why this whole task exists: the data setup travels with the code.</div>\r\n  <p>⏭️ Data is in — where does it physically live, and how do you look at it? → <a href=\"#sec-08\">Section 8</a></p>\r\n  <div class=\"folio\"><span>📘 MariaDB Provisioning · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 12 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#sec-06\">Prev</a> · <a href=\"#sec-08\">Next</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Section 08</div><h1 id=\"viewing-the-data-4-ways\">👀 Viewing the Data <span class=\"en\">— 4 Ways</span></h1></div><span class=\"hmeta\">🟡 5 MIN</span></div></div>\r\n  <p>\"Where is my data?\" has four different honest answers — each useful in a different situation, and one of them is a trap.</p>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>1️⃣ The seed file — plain text</p><div class=\"code mini\"><span class=\"p\">$</span> cat /opt/mariadb/initdb.sql</div><p>The <b>source</b> that seeded the DB — readable, versioned, rendered from the template. Read this to see <i>what was supposed to be created</i>.</p></div>\r\n    <div class=\"panel\"><p>2️⃣ On-disk storage — the trap ⚠️</p><div class=\"code mini\">/var/lib/mysql/&lt;db_name&gt;/</div><p>Binary <code>.ibd</code> files — <b>not human-readable; never edit these directly</b>. This is where the data physically lives, but it belongs to MariaDB, not to you.</p></div>\r\n    <div class=\"panel\"><p>3️⃣ Readable full snapshot</p><div class=\"code mini\"><span class=\"p\">$</span> sudo mysqldump myapp_db &gt; myapp_db_backup.sql</div><p>Schema <b>+ data</b> exported as readable SQL — the proper way to capture the complete current state (also your backup move).</p></div>\r\n    <div class=\"panel\"><p>4️⃣ Querying directly</p><div class=\"code mini\"><span class=\"p\">$</span> sudo mysql myapp_db <span class=\"y\">-e</span> <span class=\"s\">\"SELECT * FROM &lt;table&gt;;\"</span></div><p>The everyday move — ask the live server a question, get the live answer.</p></div>\r\n  </div>\r\n  <div class=\"taskhead\">TASK [Choosing a viewer]<span class=\"hst\">which one when?</span></div>\r\n  <div class=\"tblwrap\"><div class=\"table-scroll\"><table>\r\n    <tr><th>You want to…</th><th>Reach for</th></tr>\r\n    <tr><td>See what the automation intended to create</td><td>1️⃣ <code>cat initdb.sql</code></td></tr>\r\n    <tr><td>Back up or hand off the full current state</td><td>3️⃣ <code>mysqldump</code></td></tr>\r\n    <tr><td>Check rows right now</td><td>4️⃣ <code>mysql -e \"SELECT…\"</code></td></tr>\r\n    <tr><td>Satisfy curiosity about storage internals</td><td>2️⃣ <code>/var/lib/mysql/</code> — <b>look, never touch</b></td></tr>\r\n  </table></div></div>\r\n  <div class=\"mark m-warn\"><span class=\"tag\">WATCH OUT · Emphasized</span>Editing files under <code>/var/lib/mysql/</code> while MariaDB is running (or ever, really) is how databases <b>die</b>. The server owns those bytes. Your interface to the data is always SQL — through the client, or a dump.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 TAKEAWAY</span>Four views: <b>seed source</b> (initdb.sql, text) · <b>raw storage</b> (/var/lib/mysql, binary — hands off) · <b>full snapshot</b> (mysqldump, readable SQL) · <b>live query</b> (mysql -e). Each answers \"where is my data\" from a different altitude.</div>\r\n  <p>⏭️ Before you go — the three mistakes this task actually produced: → <a href=\"#sec-09\">Section 9: Gotchas</a></p>\r\n  <div class=\"folio\"><span>📘 MariaDB Provisioning · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 13 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#sec-07\">Prev</a> · <a href=\"#sec-09\">Next</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Section 09</div><h1 id=\"gotchas-lessons-from-the-trench\">⚠️ Gotchas <span class=\"en\">— Lessons From the Trench</span></h1></div><span class=\"hmeta\">🔴 real errors</span></div></div>\r\n  <p>Three things that actually went sideways while building this task. Each one costs minutes (or hours) the first time — reading them here costs you seconds.</p>\r\n  <div class=\"mark m-fail\"><span class=\"tag\">GOTCHA 1 · Two interpreters, one prompt</span>The <code>mysql</code> client and the bash shell are <b>two different command interpreters</b>. SQL pasted into bash — or shell commands pasted into an open <code>mysql</code> session — produces <b>confusing, unrelated errors</b>. Always check the prompt before typing:</div>\r\n  <div class=\"grid2\">\r\n    <div class=\"panel\"><p>💵 <code>$</code> means bash</p><p>Shell commands live here: <code>sudo systemctl…</code>, <code>cat</code>, <code>mysql -e \"…\"</code>. SQL typed here = <code>syntax error</code> nonsense.</p></div>\r\n    <div class=\"panel\"><p>🐬 <code>MariaDB [db]&gt;</code> means mysql</p><p>SQL lives here: <code>SELECT…</code>, <code>SHOW…</code>. Shell commands typed here = <code>ERROR 1064</code> nonsense.</p></div>\r\n  </div>\r\n  <div class=\"mark m-fail\"><span class=\"tag\">GOTCHA 2 · Multi-line SQL</span>Multi-line SQL is safest <b>saved to a <code>.sql</code> file and piped in</b> (<code>mysql … &lt; file.sql</code>) rather than pasted interactively. Pasting long statements into the client invites partial-line errors, lost semicolons, and copy bugs — the file is repeatable, the paste is a gamble.</div>\r\n  <div class=\"mark m-fail\"><span class=\"tag\">GOTCHA 3 · bind-address = 127.0.0.1</span>The deployed config sets <code>bind-address = 127.0.0.1</code> — the server <b>only accepts local connections</b>. This is <b>intentional for a dev/local setup</b>: the database simply isn't reachable from other machines. If remote access is ever needed, change the bind address <b>and</b> open the firewall — both, or it still won't answer.</div>\r\n  <div class=\"zone\">\r\n    <div class=\"zlabel\">Remote access checklist — only when needed</div>\r\n    <div class=\"frow\">\r\n      <span class=\"chipr\">1️⃣ change bind-address</span>\r\n      <span class=\"harrow\">+</span>\r\n      <span class=\"chipr\">2️⃣ open the firewall</span>\r\n      <span class=\"harrow\">+</span>\r\n      <span class=\"chipr\">3️⃣ user host ≠ localhost</span>\r\n      <span class=\"harrow\">──►</span>\r\n      <span class=\"chipr\">reachable</span>\r\n    </div>\r\n    <p>Note the 3️⃣: the default grant is <code>myapp_user@localhost</code> — a remote client needs a matching user/host too.</p>\r\n  </div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA</span>All three gotchas share one root: <b>the error appears far from its cause</b>. Wrong interpreter, wrong input channel, wrong bind address — each one looks like a totally different problem than it is. Slow down, check the prompt, check the file, check the config.</div>\r\n  <div class=\"m-exam\"><span class=\"tag\">🎓 TAKEAWAY</span>The trench notes: <b>1.</b> prompt tells you the language ($ = bash, MariaDB [&gt;] = SQL) · <b>2.</b> pipe multi-line SQL from a file · <b>3.</b> bind-address 127.0.0.1 = local-only by design; remote needs config + firewall + user host.</div>\r\n  <p>⏭️ All sections complete — the condensed reference: → <a href=\"#cheatsheet\">Cheat Sheet</a></p>\r\n  <div class=\"folio\"><span>📘 MariaDB Provisioning · <span class=\"by\">By Nabawy</span></span><span class=\"fnum\">— 14 —</span><span><a href=\"#toc\">▤ TOC</a> ◀ <a href=\"#sec-08\">Prev</a> · <a href=\"#cheatsheet\">Next</a></span></div>\r\n</div>\r\n\r\n\r\n<div class=\"sheet\">\r\n  <div class=\"pghead\"><div class=\"hrow\"><div><div class=\"kick\">Cheat Sheet</div><h1 id=\"the-cheat-sheet-print-amp-pin-it\">📌 The Cheat Sheet — print &amp; pin it</h1></div><span class=\"hmeta\">PRINT ME 🖨️</span></div></div>\r\n  <div class=\"tree\">▶ <b>THE TASK:</b>     Ansible provisions MariaDB — 8 steps, one role, fully reproducible\r\n▶ <b>END STATE:</b>    running server + /opt/mariadb config + myapp_db + myapp_user + seeded schema\r\n▶ <b>THE FLOW:</b>     install → service → folder → templates+symlink → restart(flush) → db → user → import</div>\r\n  <div class=\"grid2\">\r\n    <div>\r\n      <div class=\"zlabel\">⚙️ Run &amp; Verify</div>\r\n      <div class=\"code mini\"><span class=\"p\">$</span> ansible-galaxy collection install <span class=\"y\">-r</span> requirements.yml\r\n<span class=\"p\">$</span> ansible-playbook <span class=\"y\">-i</span> inventory.ini playbook.yml \\\r\n    <span class=\"y\">--ask-become-pass</span> \\\r\n    <span class=\"y\">-e</span> mariadb_db_password=<span class=\"s\">'…'</span>\r\n\r\n<span class=\"g\"># verify (5 checks):</span>\r\n<span class=\"p\">$</span> sudo systemctl status mariadb\r\n<span class=\"p\">$</span> sudo mysql <span class=\"y\">-e</span> <span class=\"s\">\"SHOW VARIABLES LIKE 'character_set_server';\"</span>\r\n<span class=\"p\">$</span> sudo mysql <span class=\"y\">-e</span> <span class=\"s\">\"SHOW DATABASES;\"</span>\r\n<span class=\"p\">$</span> sudo mysql <span class=\"y\">-e</span> <span class=\"s\">\"SHOW GRANTS FOR 'myapp_user'@'localhost';\"</span>\r\n<span class=\"p\">$</span> sudo mysql myapp_db <span class=\"y\">-e</span> <span class=\"s\">\"SELECT * FROM app_info;\"</span></div>\r\n      <div class=\"zlabel\">🗄️ Data Access</div>\r\n      <div class=\"code mini\"><span class=\"p\">$</span> cat /opt/mariadb/initdb.sql        <span class=\"g\"># seed source</span>\r\n<span class=\"p\">$</span> sudo mysqldump myapp_db &gt; backup.sql <span class=\"g\"># snapshot</span>\r\n<span class=\"p\">$</span> sudo mysql myapp_db <span class=\"y\">-e</span> <span class=\"s\">\"SELECT…;\"</span>  <span class=\"g\"># live query</span>\r\n<span class=\"r\">/var/lib/mysql/ — binary, NEVER edit</span></div>\r\n    </div>\r\n    <div>\r\n      <div class=\"zlabel\">🗺️ Key Paths</div>\r\n      <div class=\"table-scroll\"><table>\r\n        <tr><td>playbook.yml</td><td>entry point</td></tr>\r\n        <tr><td>inventory.ini</td><td>targets (local: ansible_connection=local)</td></tr>\r\n        <tr><td>roles/mariadb/tasks/</td><td>the 8 steps</td></tr>\r\n        <tr><td>templates/my.cnf.j2</td><td>server config source</td></tr>\r\n        <tr><td>templates/initdb.sql.j2</td><td>schema + seed source</td></tr>\r\n        <tr><td>/opt/mariadb/</td><td>deployed config + init script</td></tr>\r\n        <tr><td>/etc/mysql/mariadb.conf.d/99-custom.cnf</td><td>Debian symlink</td></tr>\r\n        <tr><td>/etc/my.cnf.d/</td><td>RedHat symlink target</td></tr>\r\n      </table></div>\r\n      <div class=\"zlabel\">🚨 The 8 Steps</div>\r\n      <div class=\"table-scroll\"><table>\r\n        <tr><td>1</td><td>install mariadb + PyMySQL</td></tr>\r\n        <tr><td>2</td><td>enable + start service</td></tr>\r\n        <tr><td>3</td><td>create /opt/mariadb</td></tr>\r\n        <tr><td>4</td><td>deploy my.cnf + initdb.sql + symlink</td></tr>\r\n        <tr><td>5</td><td>restart via handler + flush</td></tr>\r\n        <tr><td>6</td><td>mysql_db → create myapp_db</td></tr>\r\n        <tr><td>7</td><td>mysql_user → myapp_user + grants</td></tr>\r\n        <tr><td>8</td><td>mysql_db import → initdb.sql</td></tr>\r\n      </table></div>\r\n    </div>\r\n  </div>\r\n  <div class=\"frow\">\r\n    <span class=\"chipr\">bind-address 127.0.0.1 = local-only</span>\r\n    <span class=\"chipr\">$ = bash · MariaDB [&gt;] = SQL</span>\r\n    <span class=\"chipr\">pipe SQL from .sql files</span>\r\n  </div>\r\n  <div class=\"mark m-key\"><span class=\"tag\">KEY IDEA · Closing line</span><b>One role, eight steps, five verification checks — and the same MariaDB server comes out the other side every single time. That's infrastructure as code doing exactly what it says.</b> ▶</div>\r\n  <div class=\"folio\"><span>📘 MariaDB Provisioning · <span class=\"by\">By Nabawy</span> · REDLINE Daylight</span><span class=\"fnum\">— 15 —</span><span><a href=\"#toc\">▤ TOC</a></span><span>▶ The End 🎬</span></div>\r\n</div>\r\n\r\n\r\n","toc":[{"id":"mariadb-provisioningwith-ansible","text":"MariaDB Provisioningwith Ansible","level":1},{"id":"table-of-contents","text":"📖 Table of Contents","level":1},{"id":"the-map-the-whole-task","text":"🗺️ The Map — The Whole Task","level":1},{"id":"objective-amp-end-state","text":"🎯 Objective &amp; End State","level":1},{"id":"the-tools-what-amp-why","text":"🧰 The Tools — What &amp; Why","level":1},{"id":"project-structure-the-tree","text":"🌳 Project Structure — The Tree","level":1},{"id":"steps-1-3-install-service-folder","text":"🧱 Steps 1–3 — Install · Service · Folder","level":1},{"id":"steps-4-5-config-deploy-restart","text":"📄 Steps 4–5 — Config Deploy + Restart","level":1},{"id":"steps-6-8-db-user-seed","text":"🐬 Steps 6–8 — DB · User · Seed","level":1},{"id":"running-it-the-commands","text":"▶️ Running It — The Commands","level":1},{"id":"verifying-the-result","text":"✅ Verifying the Result","level":1},{"id":"adding-new-data-two-paths","text":"➕ Adding New Data — Two Paths","level":1},{"id":"viewing-the-data-4-ways","text":"👀 Viewing the Data — 4 Ways","level":1},{"id":"gotchas-lessons-from-the-trench","text":"⚠️ Gotchas — Lessons From the Trench","level":1},{"id":"the-cheat-sheet-print-amp-pin-it","text":"📌 The Cheat Sheet — print &amp; pin it","level":1}],"words":4644,"assets":[]};